import { Avatar } from '@/components/avatar/Avatar';
import { Badge } from '@/components/badge/Badge';
import { Button } from '@/components/button/Button';
import { Card } from '@/components/card/Card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
} from '@/components/table/Table';
import { ToolbarGroup } from '@/components/toolbar/Toolbar';
import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { cn } from '@/lib/utils';
import {
  type Column,
  type ColumnResizeMode,
  type ExpandedState,
  type HeaderGroup,
  type Row,
  type RowSelectionState,
  type SortingState,
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { Fragment, memo, useMemo, useState } from 'react';
import { ActionBar, FilterButton } from './action-bar';
import { emissionColumns } from './columns';
import {
  type EmissionTreeRow,
  buildEmissionTree,
  emissions,
  getEmissionLeaves,
} from './data';
import {
  CATEGORY_TITLE_LEFT,
  FILLER_COLUMN_WIDTH,
  RAIL_STARTS,
  RAIL_WIDTHS,
  SUBCATEGORY_TITLE_LEFT,
  columnSizeVar,
  getColumnSizeVars,
  getLeafColumnsInDisplayOrder,
  getPinnedClassName,
  getPinningStyles,
  titleStickyStyle,
} from './pinning';
import { ResizeHandle } from './resize-handle';
import { ChevronCell, RailCells } from './table-rail';

function EmissionColGroup({
  columns,
}: {
  columns: Column<EmissionTreeRow>[];
}) {
  return (
    <colgroup>
      {RAIL_WIDTHS.map((width, index) => (
        <col key={`rail-${index}`} style={{ width }} />
      ))}
      {columns.map((column) => (
        <col
          key={column.id}
          style={{ width: `var(${columnSizeVar(column.id)})` }}
        />
      ))}
      {/* Absorbs whatever space is left over, so narrowing the columns below
          the card width does not end the rows mid-frame. */}
      <col style={{ width: FILLER_COLUMN_WIDTH }} />
    </colgroup>
  );
}

function EmissionHeaderRows({
  headerGroups,
}: {
  headerGroups: HeaderGroup<EmissionTreeRow>[];
}) {
  return (
    <>
      {headerGroups.map((hg) => (
        // Sticks below the category (top-0, h-9) + subcategory (top-9, h-11)
        // titles → 36 + 44 = 80px. z-[15] keeps it above source rows (pinned
        // cells z-10) but below the subcategory (z-20) and category (z-30)
        // titles. The row's z-index makes the whole header (incl. its pinned
        // cells) paint above source rows during vertical scroll.
        <TableRow
          key={hg.id}
          className="sticky top-20 z-[15] hover:bg-transparent"
        >
          <RailCells variant="vertical" />
          {hg.headers.map((header) => (
            <TableHead
              key={header.id}
              style={getPinningStyles(header.column)}
              className={cn(
                'border-b border-grayscale-opacity-300',
                getPinnedClassName(header.column),
              )}
            >
              {header.isPlaceholder ? null : (
                <span className="block overflow-hidden text-ellipsis">
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </span>
              )}
              {!header.isPlaceholder && (
                <ResizeHandle header={header} />
              )}
            </TableHead>
          ))}
          <td className="border-b border-grayscale-opacity-300 bg-white p-0" />
        </TableRow>
      ))}
    </>
  );
}

function EmissionCategoryRow({
  row,
  titleColSpan,
}: {
  row: Row<EmissionTreeRow>;
  titleColSpan: number;
}) {
  if (row.original.kind !== 'category') {
    return null;
  }

  return (
    <TableRow
      aria-expanded={row.getIsExpanded()}
      role="button"
      tabIndex={0}
      onClick={row.getToggleExpandedHandler()}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          row.toggleExpanded();
        }
      }}
      className="sticky top-0 z-30 cursor-pointer bg-[#f8f8f9] hover:bg-grayscale-200"
    >
      <td
        className="sticky z-10 bg-[#f8f8f9] p-0"
        style={{ left: RAIL_STARTS[0], width: RAIL_WIDTHS[0] }}
      />
      <td
        className="sticky z-10 bg-[#f8f8f9] p-0"
        style={{ left: RAIL_STARTS[1], width: RAIL_WIDTHS[1] }}
      />
      <ChevronCell
        expanded={row.getIsExpanded()}
        leftOffset={RAIL_STARTS[2]}
        bgClassName="bg-[#f8f8f9]"
      />
      <TableCell
        colSpan={titleColSpan}
        className="h-9 overflow-visible border-r-0 bg-transparent py-0 pl-0 pr-3 text-sm font-medium text-grayscale-opacity-900"
      >
        <div
          className="flex items-center gap-2 overflow-hidden whitespace-nowrap pr-3"
          style={titleStickyStyle(CATEGORY_TITLE_LEFT)}
        >
          <Badge variant="info" type="text" size="md">
            ISO
          </Badge>
          <Avatar fallback="" size="xs" color="tiffany" />
          <span className="truncate">{row.original.title}</span>
          <span className="ml-auto text-sm font-normal tabular-nums text-grayscale-opacity-700">
            {getEmissionLeaves(row.original).length}
          </span>
        </div>
      </TableCell>
    </TableRow>
  );
}

function EmissionSubcategoryRow({
  row,
  titleColSpan,
}: {
  row: Row<EmissionTreeRow>;
  titleColSpan: number;
}) {
  if (row.original.kind !== 'subcategory') {
    return null;
  }

  return (
    <TableRow
      aria-expanded={row.getIsExpanded()}
      role="button"
      tabIndex={0}
      onClick={row.getToggleExpandedHandler()}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          row.toggleExpanded();
        }
      }}
      className="sticky top-9 z-20 cursor-pointer bg-white hover:bg-grayscale-opacity-100"
    >
      <RailCells
        variant="branch"
        trailingCell={
          <ChevronCell
            expanded={row.getIsExpanded()}
            leftOffset={RAIL_STARTS[3]}
          />
        }
      />
      <TableCell
        colSpan={titleColSpan}
        className="h-11 overflow-visible border-r-0 bg-transparent py-0 pl-0 pr-3 text-sm font-medium text-grayscale-opacity-800"
      >
        <div
          className="flex items-center gap-2 overflow-hidden whitespace-nowrap pr-3"
          style={titleStickyStyle(SUBCATEGORY_TITLE_LEFT)}
        >
          <Badge variant="info" type="text" size="md">
            ISO
          </Badge>
          <Avatar fallback="" size="xs" color="tiffany" />
          <span className="truncate">{row.original.title}</span>
          <span className="ml-auto text-sm font-normal tabular-nums text-grayscale-opacity-700">
            {getEmissionLeaves(row.original).length}
          </span>
        </div>
      </TableCell>
    </TableRow>
  );
}

function EmissionSourceRow({ row }: { row: Row<EmissionTreeRow> }) {
  return (
    <TableRow>
      <RailCells variant="vertical" />
      {row.getVisibleCells().map((cell) => {
        const pinStyle = getPinningStyles(cell.column);
        const pinClass = getPinnedClassName(cell.column);

        if (cell.column.id === 'id') {
          return (
            <TableHead
              key={cell.id}
              scope="row"
              style={pinStyle}
              className={cn(
                'h-11 border-b border-grayscale-opacity-300 bg-transparent px-3 py-1 align-middle font-normal text-grayscale-opacity-800',
                pinClass,
              )}
            >
              {flexRender(
                cell.column.columnDef.cell,
                cell.getContext(),
              )}
            </TableHead>
          );
        }

        return (
          <TableCell
            key={cell.id}
            style={pinStyle}
            className={cn(
              'border-b border-grayscale-opacity-300 bg-transparent',
              pinClass,
            )}
          >
            {flexRender(
              cell.column.columnDef.cell,
              cell.getContext(),
            )}
          </TableCell>
        );
      })}
      <td className="border-b border-grayscale-opacity-300 p-0" />
    </TableRow>
  );
}

interface EmissionCategorySectionProps {
  row: Row<EmissionTreeRow>;
  headerGroups: HeaderGroup<EmissionTreeRow>[];
  categoryTitleColSpan: number;
  subcategoryTitleColSpan: number;
  isResizing: boolean;
}

function EmissionCategorySection({
  row,
  headerGroups,
  categoryTitleColSpan,
  subcategoryTitleColSpan,
}: EmissionCategorySectionProps) {
  return (
    <TableBody>
      <EmissionCategoryRow
        row={row}
        titleColSpan={categoryTitleColSpan}
      />
      {row.getIsExpanded() &&
        row.subRows.map((subcategoryRow) => (
          <Fragment key={subcategoryRow.id}>
            <EmissionSubcategoryRow
              row={subcategoryRow}
              titleColSpan={subcategoryTitleColSpan}
            />
            {subcategoryRow.getIsExpanded() && (
              <>
                <EmissionHeaderRows headerGroups={headerGroups} />
                {subcategoryRow.subRows.map((sourceRow) => (
                  <EmissionSourceRow
                    key={sourceRow.id}
                    row={sourceRow}
                  />
                ))}
              </>
            )}
          </Fragment>
        ))}
    </TableBody>
  );
}

/**
 * Column widths come from CSS variables on `<table>`, so a drag does not need
 * to re-render a single row — freeze the sections until it ends. Without this
 * every `mousemove` rebuilds the whole tree (measured ~50ms/frame here, vs the
 * ~14ms idle frame).
 */
const MemoEmissionCategorySection = memo(
  EmissionCategorySection,
  (_prev, next) => next.isResizing,
);

export interface DataTableGroup02Props {
  /**
   * `'onChange'` moves the columns under the pointer; `'onEnd'` holds them and
   * commits on release, with the guide line showing where the edge will land.
   * This table is wide and heavily pinned, so `'onEnd'` is noticeably smoother
   * — it does no layout work while dragging.
   */
  columnResizeMode?: ColumnResizeMode;
}

export function DataTableGroup02({
  columnResizeMode = 'onChange',
}: DataTableGroup02Props = {}) {
  const [sorting, setSorting] = useState<SortingState>([]);
  // `true` expands every row by default (vs `{}` which collapses all).
  const [expanded, setExpanded] = useState<ExpandedState>(true);
  const [rowSelection, setRowSelection] = useState<RowSelectionState>(
    {},
  );
  const data = useMemo(() => buildEmissionTree(emissions), []);
  const table = useReactTable({
    data,
    columns: emissionColumns,
    state: { expanded, rowSelection, sorting },
    initialState: {
      columnPinning: { left: ['select', 'id'] },
    },
    defaultColumn: { minSize: 48, maxSize: 480 },
    columnResizeMode,
    enableRowSelection: true,
    onExpandedChange: setExpanded,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    getSubRows: (row) =>
      row.kind === 'source' ? undefined : row.subRows,
    getCoreRowModel: getCoreRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });
  const visibleColumns = getLeafColumnsInDisplayOrder(table);
  const isResizing = Boolean(
    table.getState().columnSizingInfo.isResizingColumn,
  );
  // Total cols = 4 rail tracks + data cols + 1 trailing fill col.
  // Category title spans everything to the right of the chevron (col 3).
  // Subcategory title spans everything to the right of its chevron (col 4).
  const categoryTitleColSpan = visibleColumns.length + 2;
  const subcategoryTitleColSpan = visibleColumns.length + 1;

  return (
    <Card className="w-full max-w-[1408px]">
      <ActionBar
        searchPlaceholder="搜尋"
        left={
          <ToolbarGroup>
            <FilterButton>負責人</FilterButton>
            <FilterButton>審核人</FilterButton>
          </ToolbarGroup>
        }
        right={
          <ToolbarGroup>
            <FilterButton>分群:排放源</FilterButton>
            <FilterButton>顯示欄位</FilterButton>
            <FilterButton>審核:開啟</FilterButton>
            <Button variant="default" theme="default">
              填報欄位名稱
            </Button>
            <Button variant="default" theme="primary">
              新增
              <ChevronDownIcon data-icon="inline-end" />
            </Button>
          </ToolbarGroup>
        }
      />
      <Table
        className={cn(
          'table-fixed border-separate border-spacing-0',
          isResizing && '[&_*]:cursor-col-resize',
        )}
        containerClassName="max-h-[560px] overflow-auto"
        style={{
          ...getColumnSizeVars(table),
          minWidth: 'max(1408px, var(--table-total-size))',
        }}
      >
        <EmissionColGroup columns={visibleColumns} />
        {table
          .getRowModel()
          .rows.filter((row) => row.depth === 0)
          .map((categoryRow) => (
            <MemoEmissionCategorySection
              key={categoryRow.id}
              row={categoryRow}
              headerGroups={table.getHeaderGroups()}
              categoryTitleColSpan={categoryTitleColSpan}
              subcategoryTitleColSpan={subcategoryTitleColSpan}
              isResizing={isResizing}
            />
          ))}
      </Table>
    </Card>
  );
}

import { Button } from '@/components/button/Button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/dropdown-menu/DropdownMenu';
import { SearchBar } from '@/components/search-bar/SearchBar';
import { Toolbar, ToolbarSpacer } from '@/components/toolbar/Toolbar';
import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { EllipsisIcon } from '@/icons/EllipsisIcon';
import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';

export function ActionBar({
  searchPlaceholder,
  left,
  right,
  raised = false,
  minWidthClassName,
}: {
  searchPlaceholder: string;
  left?: ReactNode;
  right?: ReactNode;
  raised?: boolean;
  minWidthClassName?: string;
}) {
  return (
    <Toolbar
      size="sm"
      className={cn(
        'h-12 flex-nowrap gap-6 overflow-x-auto overflow-y-hidden rounded bg-white px-3 py-2',
        '[&_[data-slot=toolbar-group]]:shrink-0',
        raised && 'shadow-emphasis',
        minWidthClassName,
      )}
    >
      <SearchBar
        placeholder={searchPlaceholder}
        width="200px"
        className="h-8 shrink-0 rounded border-none"
      />
      {left}
      <ToolbarSpacer />
      {right}
    </Toolbar>
  );
}

export function FilterButton({ children }: { children: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            theme="default"
            className="h-8 rounded-full px-3 font-normal"
          >
            {children}
            <ChevronDownIcon data-icon="inline-end" />
          </Button>
        }
      />
      <DropdownMenuContent>
        <DropdownMenuItem>全部</DropdownMenuItem>
        <DropdownMenuItem>已指派</DropdownMenuItem>
        <DropdownMenuItem>未指派</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function MoreButton() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            aria-label="更多操作"
            variant="text"
            size="icon-md"
            theme="default"
          >
            <EllipsisIcon />
          </Button>
        }
      />
      <DropdownMenuContent align="start">
        <DropdownMenuGroup>
          <DropdownMenuItem>編輯</DropdownMenuItem>
          <DropdownMenuItem>複制</DropdownMenuItem>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>刪除</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { Avatar } from '@/components/avatar/Avatar';
import { Checkbox } from '@/components/checkbox/Checkbox';
import { Switch } from '@/components/switch/Switch';
import { Tag } from '@/components/tag/Tag';
import type { ColumnDef } from '@tanstack/react-table';
import { MoreButton } from './action-bar';
import type { EmissionTreeRow } from './data';
import { DataTableColumnHeader } from './data-table-column-header';

export const emissionColumns: ColumnDef<EmissionTreeRow>[] = [
  {
    id: 'select',
    header: ({ table }) => (
      <Checkbox
        aria-label="Select all"
        checked={table.getIsAllPageRowsSelected()}
        indeterminate={table.getIsSomePageRowsSelected()}
        onCheckedChange={(value) =>
          table.toggleAllPageRowsSelected(Boolean(value))
        }
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select row ${row.original.id}`}
        checked={row.getIsSelected()}
        onCheckedChange={(value) =>
          row.toggleSelected(Boolean(value))
        }
      />
    ),
    size: 40,
    minSize: 40,
    maxSize: 40,
    enableSorting: false,
    enableResizing: false,
  },
  {
    accessorKey: 'id',
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="序" />
    ),
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.id : null,
    size: 38,
    minSize: 38,
    enableSorting: false,
  },
  {
    id: 'source',
    accessorFn: (row) => (row.kind === 'source' ? row.source : ''),
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="排放源" />
    ),
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.source : null,
    size: 164,
  },
  {
    id: 'formula',
    accessorFn: (row) => (row.kind === 'source' ? row.formula : ''),
    header: '係數名稱',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.formula : null,
    size: 312,
    enableSorting: false,
  },
  {
    id: 'count',
    accessorFn: (row) => (row.kind === 'source' ? row.count : 0),
    header: '據點數',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.count : null,
    size: 66,
    enableSorting: false,
  },
  {
    id: 'owner',
    accessorFn: (row) => (row.kind === 'source' ? row.owner : ''),
    header: '負責人',
    cell: ({ row }) =>
      row.original.kind !== 'source' ? null : row.original.owner ===
        '未指派' ? (
        <Avatar fallback="?" size="sm" color="orange" />
      ) : (
        <Avatar
          fallback={row.original.owner}
          name={row.original.owner}
          size="sm"
          color="tiffany"
        />
      ),
    size: 102,
    enableSorting: false,
  },
  {
    id: 'reviewer',
    accessorFn: (row) => (row.kind === 'source' ? row.reviewer : ''),
    header: '審核人',
    cell: ({ row }) =>
      row.original.kind !== 'source' ? null : row.original
          .reviewer === '未指派' ? (
        <Avatar fallback="?" size="sm" color="orange" />
      ) : (
        <Avatar
          fallback={row.original.reviewer}
          name={row.original.reviewer}
          size="sm"
          color="tiffany"
        />
      ),
    size: 102,
    enableSorting: false,
  },
  {
    id: 'template',
    accessorFn: (row) => (row.kind === 'source' ? row.template : ''),
    header: '填報樣板',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.template : null,
    size: 116,
    enableSorting: false,
  },
  {
    id: 'reference',
    accessorFn: (row) =>
      row.kind === 'source' ? row.reference : null,
    header: '引用排放源',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.reference : null,
    size: 104,
    enableSorting: false,
  },
  {
    id: 'tag',
    accessorFn: (row) => (row.kind === 'source' ? row.tag : null),
    header: '標籤',
    cell: ({ row }) =>
      row.original.kind === 'source' && row.original.tag ? (
        <Tag color="gold" colorVariant="tint">
          {row.original.tag}
        </Tag>
      ) : null,
    size: 76,
    enableSorting: false,
  },
  {
    id: 'significant',
    header: '重大',
    cell: () => null,
    size: 48,
    enableSorting: false,
  },
  {
    id: 'quantified',
    header: '量化',
    cell: ({ row }) =>
      row.original.kind === 'source' ? (
        <Switch defaultChecked={row.original.quantified} />
      ) : null,
    size: 68,
    enableSorting: false,
  },
  {
    id: 'note',
    header: '備註',
    cell: () => null,
    size: 48,
    enableSorting: false,
  },
  {
    id: 'actions',
    header: '',
    cell: () => <MoreButton />,
    size: 36,
    minSize: 36,
    maxSize: 36,
    enableSorting: false,
    enableResizing: false,
  },
];

import { CaretDownIcon } from '@/icons/CaretDownIcon';
import { CaretUpIcon } from '@/icons/CaretUpIcon';
import { cn } from '@/lib/utils';
import type { Column } from '@tanstack/react-table';
import type { ReactNode } from 'react';

export interface DataTableColumnHeaderProps<TData, TValue> {
  column: Column<TData, TValue>;
  title: ReactNode;
  className?: string;
}

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return (
      <span className={cn('block truncate', className)}>{title}</span>
    );
  }

  const sort = column.getIsSorted();

  return (
    <button
      type="button"
      data-slot="data-table-column-header"
      data-sort={sort || undefined}
      onClick={column.getToggleSortingHandler()}
      className={cn(
        'inline-flex max-w-full cursor-pointer items-center gap-1 font-normal text-grayscale-opacity-800 transition-colors hover:text-grayscale-opacity-900 focus-visible:shadow-focus-primary focus-visible:outline-none',
        className,
      )}
    >
      <span className="truncate">{title}</span>
      <span
        aria-hidden="true"
        className="inline-flex size-4 shrink-0 flex-col items-center justify-center"
      >
        <CaretUpIcon
          className={cn(
            'size-2',
            sort === 'asc'
              ? 'text-grayscale-opacity-800'
              : 'text-grayscale-opacity-400',
          )}
        />
        <CaretDownIcon
          className={cn(
            'size-2',
            sort === 'desc'
              ? 'text-grayscale-opacity-800'
              : 'text-grayscale-opacity-400',
          )}
        />
      </span>
    </button>
  );
}

import type { Column, Table } from '@tanstack/react-table';
import type { CSSProperties } from 'react';
import type { EmissionTreeRow } from './data';

export const RAIL_WIDTHS = [4, 28, 24, 24] as const;
export const RAIL_STARTS = [0, 4, 32, 56] as const; // cumulative left of each rail col
export const RAIL_OFFSET = RAIL_WIDTHS.reduce((sum, w) => sum + w, 0); // 80
export const CATEGORY_TITLE_LEFT = RAIL_STARTS[3]; // chevron in col 3, title starts at col 4
export const SUBCATEGORY_TITLE_LEFT = RAIL_OFFSET; // chevron in col 4, title starts at col 5

/**
 * Column ids may contain characters that are not valid in a CSS custom
 * property name, so they are slugified before being used as a variable.
 */
function slug(columnId: string) {
  return columnId.replace(/[^\w-]/g, '-');
}

export function columnSizeVar(columnId: string) {
  return `--col-${slug(columnId)}-size`;
}

function columnStartVar(columnId: string) {
  return `--col-${slug(columnId)}-start`;
}

/** Same order as `getHeaderGroups()`: left pins, unpinned, right pins. */
export function getLeafColumnsInDisplayOrder<TData>(
  table: Table<TData>,
) {
  return [
    ...table.getLeftVisibleLeafColumns(),
    ...table.getCenterVisibleLeafColumns(),
    ...table.getRightVisibleLeafColumns(),
  ];
}

/**
 * Widths and pinned offsets as CSS variables, set once on `<table>`.
 *
 * Column resizing then only rewrites that one `style` attribute: the colgroup
 * widths and every pinned `left` offset read from these variables, so the rows
 * do not have to re-render mid-drag. Pinned offsets have to be included because
 * widening a pinned column pushes the pinned columns after it to the right.
 */
export function getColumnSizeVars<TData>(
  table: Table<TData>,
): CSSProperties {
  const vars: Record<string, string> = {
    // The rail occupies RAIL_OFFSET px before the first data column.
    '--table-total-size': `${RAIL_OFFSET + table.getTotalSize()}px`,
  };

  for (const column of table.getVisibleLeafColumns()) {
    vars[columnSizeVar(column.id)] = `${column.getSize()}px`;
    vars[columnStartVar(column.id)] = `${column.getStart('left')}px`;
  }

  return vars as CSSProperties;
}

/**
 * Width for the trailing filler column.
 *
 * Under `table-fixed` a percentage column is clamped to the space the sized
 * columns leave over, so `100%` means "take the slack, or nothing": it is 0 when
 * the columns already fill the frame and exactly the leftover when they don't.
 * The sized columns therefore always render at the width they were dragged to.
 *
 * `auto` does NOT work here — Chrome hands an unsized column an equal share of
 * the table width (and widens the table to fit it) instead of the leftover.
 */
export const FILLER_COLUMN_WIDTH = '100%';

export function titleStickyStyle(leftOffset: number): CSSProperties {
  return {
    position: 'sticky',
    left: leftOffset,
    width: `min(${1408 - leftOffset}px, calc(100vw - ${leftOffset + 48}px))`,
  };
}

export function getPinningStyles(
  column: Column<EmissionTreeRow>,
): CSSProperties {
  if (column.getIsPinned() !== 'left') {
    return {};
  }

  return {
    position: 'sticky',
    // Pinned columns start after the rail, then stack by their own widths.
    left: `calc(${RAIL_OFFSET}px + var(${columnStartVar(column.id)}))`,
    width: `var(${columnSizeVar(column.id)})`,
    zIndex: 10,
    boxShadow: column.getIsLastColumn('left')
      ? 'inset -1px 0 0 var(--grayscale-opacity-300)'
      : undefined,
  };
}

export function getPinnedClassName(column: Column<EmissionTreeRow>) {
  // Pinned cells need a solid bg so scrolling content doesn't bleed through.
  // We lose the TR hover bg for these cells — acceptable for identity columns.
  return column.getIsPinned() === 'left' ? 'bg-white' : undefined;
}

import { cn } from '@/lib/utils';
import type { Header } from '@tanstack/react-table';
import type { MouseEvent, TouchEvent } from 'react';

const NUDGE_STEP = 8;
const NUDGE_STEP_LARGE = 40;
const RAISED_Z = '60';
const TOUCH_MOVE_OPTS: AddEventListenerOptions = {
  capture: true,
  passive: false,
};
const TOUCH_END_OPTS: AddEventListenerOptions = { capture: true };

type Ghost = {
  startX: number;
  size: number;
  minSize: number;
  maxSize: number;
};

function pointerClientX(
  event: globalThis.MouseEvent | globalThis.TouchEvent,
) {
  if ('touches' in event) {
    // `touchend` has an empty `touches` list; the lifted finger is only in
    // `changedTouches`. TanStack's `onEnd(e.touches[0]?.clientX)` hits this.
    return (
      event.touches[0]?.clientX ?? event.changedTouches[0]?.clientX
    );
  }
  return event.clientX;
}

function clampedGhostWidth(ghost: Ghost, clientX: number) {
  return Math.min(
    Math.max(ghost.size + clientX - ghost.startX, ghost.minSize),
    ghost.maxSize,
  );
}

/**
 * The drag guide runs from the header down through the body, so its height
 * cannot come from the `th` it lives in. Measure the scroll container once per
 * drag and hand the value to CSS.
 *
 * Measuring (instead of using a huge value) keeps the guide from adding
 * scrollable overflow, and keeping it inside the `th` means a pinned column's
 * guide inherits that cell's sticky offset for free.
 *
 * A layout can repeat the header row per group (see `data-table-group-02`), and
 * those later rows are sticky with a z-index, so a single segment drawn from
 * the grabbed handle gets painted over and the line comes out broken. Every
 * copy of the column therefore draws its own segment from its own row down to
 * the end of the content; overlapped, they read as one continuous line.
 *
 * In `onEnd` mode the guide has to track the pointer, and it does so
 * imperatively: a layout may memoize its rows and freeze them for the drag
 * (`data-table-group-01` / `-02` do), which would freeze a React-driven ghost
 * offset along with them and leave the drag with no feedback at all.
 */
function startResizeGuide(
  handle: HTMLElement,
  ghost: Ghost | null,
  onCommit?: (width: number) => void,
) {
  const container = handle.closest<HTMLElement>(
    '[data-slot="table-container"]',
  );
  if (!container) return;

  const { columnId } = handle.dataset;
  const containerTop = container.getBoundingClientRect().top;
  const guides = Array.from(
    container.querySelectorAll<HTMLElement>(
      '[data-slot="data-table-resize-handle"]',
    ),
  ).filter((guide) => guide.dataset.columnId === columnId);

  // Sticky group-title rows sit above the header rows and would clip the
  // segments, so the cells hosting a guide are lifted for the drag and put back
  // afterwards. `RAISED_Z` clears the highest layer these layouts use (the
  // group title at z-50 in `data-table-group-01`).
  const raised: { el: HTMLElement; zIndex: string }[] = [];
  const raise = (el: Element | null) => {
    if (!(el instanceof HTMLElement)) return;
    raised.push({ el, zIndex: el.style.zIndex });
    el.style.zIndex = RAISED_Z;
  };

  for (const guide of guides) {
    const top =
      guide.getBoundingClientRect().top -
      containerTop +
      container.scrollTop;
    guide.style.setProperty(
      '--table-resize-guide-height',
      `${container.scrollHeight - top}px`,
    );
    guide.dataset.guide = 'true';
    raise(guide.closest('th, td'));
    raise(guide.closest('tr'));
  }

  const track = (
    event: globalThis.MouseEvent | globalThis.TouchEvent,
  ) => {
    if (!ghost) return;
    const clientX = pointerClientX(event);
    if (clientX === undefined) return;
    const next = clampedGhostWidth(ghost, clientX);
    for (const guide of guides) {
      guide.style.transform = `translateX(${next - ghost.size}px)`;
    }
  };

  const clear = () => {
    for (const guide of guides) {
      delete guide.dataset.guide;
      guide.style.removeProperty('--table-resize-guide-height');
      guide.style.removeProperty('transform');
    }
    for (const { el, zIndex } of raised) {
      el.style.zIndex = zIndex;
    }
    window.removeEventListener('mousemove', track);
    window.removeEventListener('mouseup', clear);
    window.removeEventListener('touchmove', track, TOUCH_MOVE_OPTS);
    window.removeEventListener(
      'touchend',
      onTouchEnd,
      TOUCH_END_OPTS,
    );
  };

  const onTouchEnd = (event: globalThis.TouchEvent) => {
    const clientX = pointerClientX(event);
    if (ghost && onCommit && clientX !== undefined) {
      onCommit(clampedGhostWidth(ghost, clientX));
    }
    clear();
  };

  if (ghost) {
    window.addEventListener('mousemove', track);
    // TanStack stopPropagates touchmove/touchend on `document`, so window
    // bubble never runs; capture on window sees the event first.
    window.addEventListener('touchmove', track, TOUCH_MOVE_OPTS);
  }
  window.addEventListener('mouseup', clear);
  window.addEventListener('touchend', onTouchEnd, TOUCH_END_OPTS);
}

export interface ResizeHandleProps<TData, TValue> {
  header: Header<TData, TValue>;
  /** Accessible name. Defaults to the column id. */
  label?: string;
  className?: string;
}

/**
 * Drag target that sits on the right edge of a `TableHead`.
 *
 * - pointer / touch drag resizes the column
 * - double click or `Home` resets it to the column's `size`
 * - `ArrowLeft` / `ArrowRight` nudge by 8px (40px with `Shift`)
 *
 * With `columnResizeMode: 'onEnd'` the guide follows the pointer and the column
 * only commits on release.
 */
export function ResizeHandle<TData, TValue>({
  header,
  label,
  className,
}: ResizeHandleProps<TData, TValue>) {
  const { column } = header;
  const { table } = header.getContext();

  if (!column.getCanResize()) {
    return null;
  }

  const isResizing = column.getIsResizing();
  const minSize =
    column.columnDef.minSize ??
    table.options.defaultColumn?.minSize ??
    20;
  const maxSize =
    column.columnDef.maxSize ?? table.options.defaultColumn?.maxSize;

  const resize = (delta: number) => {
    const next = Math.min(
      Math.max(column.getSize() + delta, minSize),
      maxSize ?? Number.MAX_SAFE_INTEGER,
    );
    table.setColumnSizing((sizing) => ({
      ...sizing,
      [column.id]: next,
    }));
  };

  const startDrag = (
    event: MouseEvent<HTMLDivElement> | TouchEvent<HTMLDivElement>,
  ) => {
    // Without this the drag selects the header text it passes over.
    if (event.type === 'mousedown') event.preventDefault();
    const startX =
      'touches' in event ? event.touches[0]?.clientX : event.clientX;
    // In `onEnd` mode the column stays put during the drag, so the guide
    // itself moves to show where the edge will land.
    const ghost =
      table.options.columnResizeMode === 'onEnd' &&
      startX !== undefined
        ? {
            startX,
            size: column.getSize(),
            minSize,
            maxSize: maxSize ?? Number.MAX_SAFE_INTEGER,
          }
        : null;
    startResizeGuide(event.currentTarget, ghost, (width) => {
      table.setColumnSizing((sizing) => ({
        ...sizing,
        [column.id]: width,
      }));
    });
    header.getResizeHandler()(event);
  };

  return (
    <div
      role="separator"
      aria-orientation="vertical"
      aria-label={label ?? `Resize ${column.id} column`}
      aria-valuenow={column.getSize()}
      aria-valuemin={minSize}
      aria-valuemax={maxSize}
      tabIndex={0}
      data-slot="data-table-resize-handle"
      data-column-id={column.id}
      data-resizing={isResizing || undefined}
      onMouseDown={startDrag}
      onTouchStart={startDrag}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => {
        event.stopPropagation();
        column.resetSize();
      }}
      onKeyDown={(event) => {
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
          event.preventDefault();
          const step = event.shiftKey ? NUDGE_STEP_LARGE : NUDGE_STEP;
          resize(event.key === 'ArrowLeft' ? -step : step);
          return;
        }
        if (event.key === 'Home') {
          event.preventDefault();
          column.resetSize();
        }
      }}
      className={cn(
        'absolute inset-y-0 right-0 z-30 w-2 cursor-col-resize touch-none select-none',
        'after:absolute after:top-0 after:right-0 after:h-full after:w-px after:bg-transparent after:content-[""]',
        // Hover shows nothing but the col-resize cursor; the only blue line is
        // the drag guide.
        'focus-visible:outline-none focus-visible:after:w-0.5 focus-visible:after:bg-primary-500',
        // While dragging, the grabbed handle becomes a guide line that runs
        // down the whole body.
        'data-[guide]:after:h-[var(--table-resize-guide-height,100%)] data-[guide]:after:w-0.5 data-[guide]:after:bg-primary-500',
        className,
      )}
    />
  );
}

import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';
import { RAIL_STARTS, RAIL_WIDTHS } from './pinning';

export function RailVertical() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-border"
    />
  );
}

export function RailBranch() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute right-0 top-0 h-[22px] w-3 rounded-bl-lg border-b border-l border-border"
    />
  );
}

export function RailCells({
  variant,
  trailingCell,
  bgClassName = 'bg-white',
}: {
  variant: 'vertical' | 'branch';
  trailingCell?: ReactNode;
  bgClassName?: string;
}) {
  const cellClass = cn('sticky z-10 p-0', bgClassName);
  return (
    <>
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[0], width: RAIL_WIDTHS[0] }}
      />
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[1], width: RAIL_WIDTHS[1] }}
      />
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[2], width: RAIL_WIDTHS[2] }}
      >
        <RailVertical />
        {variant === 'branch' && <RailBranch />}
      </td>
      {trailingCell ?? (
        <td
          className={cellClass}
          style={{ left: RAIL_STARTS[3], width: RAIL_WIDTHS[3] }}
        />
      )}
    </>
  );
}

export function ChevronCell({
  expanded,
  leftOffset,
  bgClassName = 'bg-white',
}: {
  expanded: boolean;
  leftOffset: number;
  bgClassName?: string;
}) {
  return (
    <td
      className={cn('sticky z-10 p-0 text-center', bgClassName)}
      style={{ left: leftOffset, width: 24 }}
    >
      <ChevronDownIcon
        className={cn(
          'mx-auto size-3 text-grayscale-opacity-700 transition-transform',
          !expanded && '-rotate-90',
        )}
      />
    </td>
  );
}
